# fmt: on


@lru_cache(maxsize=1)
def _runs() -> Tuple[List[int], List[int]]:
    data = zlib.decompress(base64.b85decode(_BLOB))
    starts: List[int] = []
    ends: List[int] = []
    values: List[int] = []
    n = shift = 0
    for byte in data:
        n |= (byte & 0x7F) << shift
        shift += 7
        if not byte & 0x80:
            values.append(n)
            n = shift = 0
    last = 0
    for gap, length in zip(values[0::2], values[1::2]):
        start = last + gap
        starts.append(start)
        ends.append(start + length)
        last = start + length
    return starts, ends


def in_release(concept_id: int) -> bool:
    """Whether ``concept_id`` exists in the release."""
    starts, ends = _runs()
    i = bisect.bisect_right(starts, concept_id) - 1
    return i >= 0 and concept_id <= ends[i]


__all__ = ["RELEASE", "in_release"]
